let currentLang: Lang = DEFAULT_LANG;

export function setLang(lang: Lang) {
  currentLang = lang;
  if (typeof window !== "undefined") localStorage.setItem("vurso_lang", lang);
}

export function getLang(): Lang {
  if (typeof window !== "undefined") {
    const s = localStorage.getItem("vurso_lang") as Lang;
    if (s && s in LANGUAGES) { currentLang = s; return s; }
  }
  return currentLang;
}

export function t(key: string, lang?: Lang): string {
  const l = lang || currentLang;
  return T[key]?.[l] || T[key]?.lt || key;
}

export function tService(key: string): string { return t(`svc.${key}`); }
export function tStatus(s: string): string {
  const m: Record<string,string> = { queued:"st.queued", in_progress:"st.inProgress", done:"st.done", archived:"st.archived", planned:"st.planned", arrived:"st.arrived", completed:"st.done", cancelled:"st.cancelled", not_invoiced:"st.notInvoiced", invoiced:"st.invoiced", paid:"st.paid" };
  return t(m[s] || s);
}
export function tRole(r: string): string { return t(`role.${r}`); }
export function tMonth(m: number): string { return t(`mo.${m}`); }
export function tDay(d: number): string { return t(["day.sun","day.mon","day.tue","day.wed","day.thu","day.fri","day.sat"][d]||""); }
